<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;

class AzamPayTransaction extends Model
{
    use HasFactory;
    
    protected $table = 'azampay_transactions'; // Fixed table name

    // Standardized statuses for Checkout API
    const STATUS_PENDING = 'pending';
    const STATUS_PROCESSING = 'processing';
    const STATUS_COMPLETED = 'completed';
    const STATUS_FAILED = 'failed';

    protected $fillable = [
        'subscription_id',

        // Unique external reference generated by backend
        'external_id',

        // AzamPay checkout session info
        'checkout_session_id',
        'checkout_url',

        // Customer information
        'customer_phone',
        'customer_email',

        // Payment identifiers
        'azampay_transaction_id',
        'azampay_payment_id',

        // Financials
        'amount',
        'currency',

        // Status
        'status',
        'checkout_status',

        // JSON data for auditing
        'raw_response',
        'callback_data',

        // Timestamps
        'initiated_at',
        'completed_at',
        'failed_at',
    ];

    protected $casts = [
        'amount'       => 'decimal:2',
        'raw_response' => 'array',
        'callback_data'=> 'array',
        'initiated_at' => 'datetime',
        'completed_at' => 'datetime',
        'failed_at'    => 'datetime',
    ];

    public function subscription()
    {
        return $this->belongsTo(Subscription::class);
    }

    // -------------------------
    // Helper Status Checkers
    // -------------------------

    public function isCompleted()
    {
        return $this->status === self::STATUS_COMPLETED;
    }

    public function isPending()
    {
        return $this->status === self::STATUS_PENDING;
    }

    public function isFailed()
    {
        return $this->status === self::STATUS_FAILED;
    }

    public function isProcessing()
    {
        return $this->status === self::STATUS_PROCESSING;
    }

    // -------------------------
    // Query Scopes
    // -------------------------

    public function scopeByExternalId($query, $externalId)
    {
        return $query->where('external_id', $externalId);
    }

    public function scopeCompleted($query)
    {
        return $query->where('status', self::STATUS_COMPLETED);
    }

    public function scopeFailed($query)
    {
        return $query->where('status', self::STATUS_FAILED);
    }

    public function scopePending($query)
    {
        return $query->where('status', self::STATUS_PENDING);
    }
}